package com.example.inventoryservicefeb25.controller;
import com.example.inventoryservicefeb25.model.Inventory; import com.example.inventoryservicefeb25.service.InventoryService; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import jakarta.validation.constraints.Min; import jakarta.validation.constraints.Positive; import org.springframework.validation.annotation.Validated;
@RestController @Validated @RequestMapping("/inventory") public class InventoryController {private final InventoryService service;public InventoryController(InventoryService service){this.service=service;} @GetMapping("/{productId}") public int stock(@PathVariable @Positive(message="productId must be positive") Long productId){return service.getStock(productId);} @PostMapping("/{productId}") public Inventory set(@PathVariable @Positive(message="productId must be positive") Long productId,@RequestParam @Min(value=1,message="quantity must be at least 1") int quantity){return service.setStock(productId,quantity);} @PostMapping("/{productId}/reserve") public ResponseEntity<Void> reserve(@PathVariable @Positive(message="productId must be positive") Long productId,@RequestParam @Min(value=1,message="quantity must be at least 1") int quantity){service.reserve(productId,quantity);return ResponseEntity.ok().build();} @PostMapping("/{productId}/release") public ResponseEntity<Void> release(@PathVariable @Positive(message="productId must be positive") Long productId,@RequestParam @Min(value=1,message="quantity must be at least 1") int quantity){service.release(productId,quantity);return ResponseEntity.ok().build();} @PostMapping("/orders/{orderId}/reserve/{productId}") public String reserveForOrder(@PathVariable @Positive(message="orderId must be positive") Long orderId,@PathVariable @Positive(message="productId must be positive") Long productId,@RequestParam @Min(value=1,message="quantity must be at least 1") int quantity,@RequestParam(defaultValue="900") @Min(value=1,message="ttlSeconds must be positive") long ttlSeconds){return service.reserveForOrder(orderId,productId,quantity,ttlSeconds);} @PostMapping("/reservations/{reservationId}/release") public ResponseEntity<Void> releaseReservation(@PathVariable String reservationId){service.releaseReservation(reservationId);return ResponseEntity.ok().build();} @PostMapping("/reservations/{reservationId}/confirm") public ResponseEntity<Void> confirmReservation(@PathVariable String reservationId){service.confirmReservation(reservationId);return ResponseEntity.ok().build();}}
